//! cmdstan-runner: the runtime of model executables built by cmdstan-rs.
//!
//! `cmdstan-rs compile` translates a Stan program with stanc-rs and builds a small Cargo
//! project whose `main` is
//!
//! ```ignore
//! mod model {
//!     use cmdstan_runner::stanc_rs_runtime;
//!     include!("model.rs"); // generated by stanc-rs
//! }
//! fn main() {
//!     cmdstan_runner::run(
//!         cmdstan_runner::BuildInfo {
//!             build_json: include_str!("../build_info.json"),
//!             stanc_info_json: include_str!("../stanc_info.json"),
//!         },
//!         model::Model::new,
//!     )
//! }
//! ```
//!
//! The executable accepts CmdStan's command line ([`args`]), builds the model from the data,
//! runs the requested method through stan-services, writes the output files, and exits with an
//! [`ExitCode`]. The unified `cmdstan-rs sample` (and every other method command) runs this
//! executable, so both ways of running a model share one implementation.
//!
//! This crate contains no inference algorithm, no estimator, and no model code: sampling,
//! optimization, approximations, and diagnostics are stan-services' (and through it
//! stan-inference's); model evaluation is stan-model-rs' and stanc-rs'.

pub mod args;
pub mod exit;
mod methods;
pub mod output;
pub mod progress;

pub use exit::{ExitCode, Failure};
/// The adapter that runs stanc-rs models through the stan-model-rs `Model` trait.
pub use stan_model_rs_stanc;
/// The runtime that stanc-rs generated code is written against (`use stanc_rs_runtime as rt;`).
pub use stanc_rs_runtime;

/// Provenance embedded in a model executable at build time.
#[derive(Clone, Copy, Debug)]
pub struct BuildInfo {
    /// The build manifest written by `cmdstan-rs compile` (JSON): source hash, compiler and
    /// library versions, toolchain, target, profile.
    pub build_json: &'static str,
    /// stanc-rs `--info` output for the program (JSON): declared data and parameter variables.
    pub stanc_info_json: &'static str,
}

/// This crate's version.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// The usage text of a model executable.
pub fn usage(program: &str) -> String {
    let mut s = format!(
        "Usage: {program} <method> [arguments]   (CmdStan 2.40 argument syntax)\n\n\
         Methods: sample, optimize, variational, pathfinder, laplace, generate_quantities,\n\
         log_prob, diagnose.\n\
         Example: {program} sample num_samples=1000 num_warmup=1000 num_chains=4 \\\n\
         \x20   data file=data.json random seed=1234 output file=out/model.csv\n\n\
         `{program} help-all` prints the argument tree; `{program} info` prints the model's\n\
         variables and build provenance as JSON.\n\nExit codes:\n"
    );
    for (code, meaning) in ExitCode::TABLE {
        s.push_str(&format!("  {:>3}  {meaning}\n", code.code()));
    }
    s
}

/// Runs a model executable with the process arguments and exits.
///
/// `make` is the generated constructor `Model::new(data, seed)`; `seed` is the run's seed,
/// which seeds the transformed data block as in CmdStan.
pub fn run<M, F>(build: BuildInfo, make: F) -> !
where
    M: stanc_rs_runtime::Model + Sync,
    F: Fn(&stanc_rs_runtime::data::Data, u64) -> stanc_rs_runtime::Result<M>,
{
    // A non-UTF-8 argument is replaced lossily instead of panicking.
    let argv: Vec<String> = std::env::args_os()
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let program = argv
        .first()
        .and_then(|p| std::path::Path::new(p).file_name())
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|| "model".into());
    let json_errors = argv.iter().any(|a| a == "--json-errors");
    // A panic outside the chains' own guards is an internal error (exit 70), not Rust's 101.
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        methods::main(&program, &argv[1..], build, &make)
    }))
    .unwrap_or_else(|_| {
        Err(Failure::new(
            ExitCode::Internal,
            "internal error (a panic); please report it with the command line",
        ))
    });
    let code = match result {
        Ok(code) => code,
        Err(f) => {
            f.report(json_errors);
            f.code
        }
    };
    std::process::exit(code.code())
}
